import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MutableDateTime_add_TriageGen1Test {

    @Test
    public void testAdd_NullType_ThrowsException() {
        MutableDateTime dt = new MutableDateTime();
        try {
            dt.add(null, 1);
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Field must not be null", e.getMessage());
        }
    }

    @Test
    public void testAdd_AmountIsOne_DoesNothing() {
        // The implementation says: if (amount != 1) { setMillis(...) }
        // This means if amount == 1, it skips the logic.
        // Note: This is unusual behavior for an 'add' method, but we test the provided code.
        MutableDateTime dt = new MutableDateTime(1000L);
        long originalMillis = dt.getMillis();

        dt.add(DurationFieldType.year(), 1);

        assertEquals("When amount is 1, the instant should remain unchanged according to the logic", 
                     originalMillis, dt.getMillis());
    }

    @Test
    public void testAdd_AmountIsNotOne_AddsCorrectly() {
        // Testing with amount != 1 to trigger the setMillis branch
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Add 2 years
        dt.add(DurationFieldType.year(), 2);

        // Expected: 2025, 1, 1, 12, 0, 0, 0
        MutableDateTime expected = new MutableDateTime(2025, 1, 1, 12, 0, 0, 0);
        assertEquals(expected.getMillis(), dt.getMillis());
    }

    @Test
    public void testAdd_NegativeAmount_SubtractsCorrectly() {
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);

        // Add -1 month (amount is -1, which is != 1, so it executes the branch)
        dt.add(DurationFieldType.monthOfYear(), -1);

        // Expected: 2022, 12, 1, 12, 0, 0, 0
        MutableDateTime expected = new MutableDateTime(2022, 12, 1, 12, 0, 0, 0);
        assertEquals(expected.getMillis(), dt.getMillis());
    }

    @Test
    public void testAdd_ZeroAmount_DoesNothing() {
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // amount 0 != 1, so it executes setMillis(field.add(current, 0))
        dt.add(DurationFieldType.dayOfMonth(), 0);

        assertEquals(originalMillis, dt.getMillis());
    }
}
